package com.slotix.reservationcore.policy;import jakarta.validation.*;import org.springframework.http.*;import org.springframework.security.access.prepost.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/companies/{companyId}/booking-policies") public class BookingPolicyController{final BookingPolicyService service;public BookingPolicyController(BookingPolicyService s){service=s;}@PostMapping @PreAuthorize("hasRole('COMPANY_ADMIN')") ResponseEntity<Map<String,UUID>> create(@PathVariable UUID companyId,@Valid @RequestBody CreateBookingPolicyRequest q){return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("id",service.create(companyId,q)));}}
